import os
from typing import Any, Dict, Iterable, List, Optional, Sequence, Union

from google.cloud import pubsub_v1


def publish_batch(
    topic_path: str,
    messages: Sequence[Union[bytes, str, Dict[str, Any]]],
    project_id: Optional[str] = None,
) -> List[str]:
    """
    Publish a batch of messages to Google Cloud Pub/Sub.

    Each message may be:
      - bytes: published as message data
      - str: encoded as UTF-8 and published as message data
      - dict: may contain:
          - "data": bytes or str
          - "attributes": dict of string keys/values
          - any other keys are treated as attributes if "attributes" is absent

    Returns a list of Pub/Sub message IDs in the same order as the input messages.
    """
    if not project_id:
        project_id = os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCP_PROJECT")

    if "/" not in topic_path:
        if not project_id:
            raise ValueError(
                "project_id is required when topic_path is not a full Pub/Sub topic path"
            )
        topic_path = f"projects/{project_id}/topics/{topic_path}"

    publisher = pubsub_v1.PublisherClient()
    futures = []

    for message in messages:
        data: bytes
        attributes: Dict[str, str] = {}

        if isinstance(message, bytes):
            data = message
        elif isinstance(message, str):
            data = message.encode("utf-8")
        elif isinstance(message, dict):
            if "data" in message:
                raw_data = message["data"]
                if isinstance(raw_data, bytes):
                    data = raw_data
                else:
                    data = str(raw_data).encode("utf-8")
            else:
                data = b""

            if isinstance(message.get("attributes"), dict):
                attributes = {str(k): str(v) for k, v in message["attributes"].items()}
            else:
                attributes = {
                    str(k): str(v)
                    for k, v in message.items()
                    if k != "data" and k != "attributes"
                }
        else:
            raise TypeError(
                "Each message must be bytes, str, or dict with optional data/attributes"
            )

        futures.append(publisher.publish(topic_path, data=data, **attributes))

    return [future.result() for future in futures]
